/**
 * Creates a compute pass that enforces BVH volume boundary constraints for particle simulations.
 *
 * Uses direct BVH queries (no SDF precomputation) for real-time particle-mesh containment.
 * Applies penalty forces to particles that penetrate or escape the BVH boundary.
 *
 * **Use Cases:**
 * - PBF/SPH simulations contained within arbitrary meshes
 * - Boids flocking inside/outside mesh volumes
 * - Particle systems with dynamic mesh boundaries
 *
 * @example
 * import { createBVHBoundaryPass } from 'three-blocks';
 *
 * const boundaryPass = createBVHBoundaryPass(
 *   positionsBuffer,
 *   velocitiesBuffer,
 *   indexBuffer,
 *   positionBuffer,
 *   bvhNodeBuffer,
 *   {
 *     stiffness: 1000.0,
 *     damping: 0.5,
 *     particleCount: 5000,
 *     containment: true // Keep particles INSIDE the mesh
 *   }
 * );
 *
 * // In animation loop
 * renderer.compute(boundaryPass);
 *
 * @function createBVHBoundaryPass
 * @param {THREE.StorageBufferAttribute} positionsBuffer - Particle positions (vec3)
 * @param {THREE.StorageBufferAttribute} velocitiesBuffer - Particle velocities (vec3)
 * @param {THREE.StorageBufferAttribute} bvhIndexBuffer - BVH triangle indices (uvec3)
 * @param {THREE.StorageBufferAttribute} bvhPositionBuffer - BVH vertex positions (vec3)
 * @param {THREE.StorageBufferAttribute} bvhNodeBuffer - BVH node data (flat f32 array)
 * @param {Object} options - Configuration options
 * @param {number} options.particleCount - Number of particles
 * @param {number} [options.stiffness=1000.0] - Boundary stiffness coefficient
 * @param {number} [options.damping=0.5] - Velocity damping on collision
 * @param {number} [options.threshold=0.0] - Distance threshold (positive = offset from surface)
 * @param {number} [options.maxSearchDistance=10.0] - Maximum BVH search distance
 * @param {boolean} [options.containment=false] - If true, keep particles INSIDE mesh; if false, push OUT
 * @param {THREE.Matrix4} [options.boundsMatrix] - Local-to-world transform matrix
 * @param {THREE.Matrix4} [options.inverseBoundsMatrix] - World-to-local transform matrix
 * @returns {*} TSL compute node
 */
export function createBVHBoundaryPass(positionsBuffer: THREE.StorageBufferAttribute, velocitiesBuffer: THREE.StorageBufferAttribute, bvhIndexBuffer: THREE.StorageBufferAttribute, bvhPositionBuffer: THREE.StorageBufferAttribute, bvhNodeBuffer: THREE.StorageBufferAttribute, options?: {
    particleCount: number;
    stiffness?: number;
    damping?: number;
    threshold?: number;
    maxSearchDistance?: number;
    containment?: boolean;
    boundsMatrix?: THREE.Matrix4;
    inverseBoundsMatrix?: THREE.Matrix4;
}): any;
/**
 * Creates a compute pass for point cloud BVH boundary constraints.
 * Used for collision with point clouds (like Gaussian Splat centers).
 *
 * @function createPointsBVHBoundaryPass
 * @param {THREE.StorageBufferAttribute} positionsBuffer - Particle positions (vec3)
 * @param {THREE.StorageBufferAttribute} velocitiesBuffer - Particle velocities (vec3)
 * @param {THREE.StorageBufferAttribute} bvhIndexBuffer - BVH point indices (uint)
 * @param {THREE.StorageBufferAttribute} bvhPositionBuffer - BVH point positions (vec3)
 * @param {THREE.StorageBufferAttribute} bvhNodeBuffer - BVH node data (flat f32 array)
 * @param {Object} options - Configuration options
 * @param {number} options.particleCount - Number of particles
 * @param {number} [options.stiffness=1000.0] - Boundary stiffness coefficient
 * @param {number} [options.damping=0.5] - Velocity damping on collision
 * @param {number} [options.pointRadius=0.5] - Shell radius around each point
 * @param {number} [options.maxSearchDistance=10.0] - Maximum BVH search distance
 * @param {THREE.Matrix4} [options.boundsMatrix] - Local-to-world transform matrix
 * @param {THREE.Matrix4} [options.inverseBoundsMatrix] - World-to-local transform matrix
 * @returns {*} TSL compute node
 */
export function createPointsBVHBoundaryPass(positionsBuffer: THREE.StorageBufferAttribute, velocitiesBuffer: THREE.StorageBufferAttribute, bvhIndexBuffer: THREE.StorageBufferAttribute, bvhPositionBuffer: THREE.StorageBufferAttribute, bvhNodeBuffer: THREE.StorageBufferAttribute, options?: {
    particleCount: number;
    stiffness?: number;
    damping?: number;
    pointRadius?: number;
    maxSearchDistance?: number;
    boundsMatrix?: THREE.Matrix4;
    inverseBoundsMatrix?: THREE.Matrix4;
}): any;
/**
 * BVHVolumeConstraint - Direct BVH boundary constraint for particle simulations.
 *
 * Unlike SDFVolumeConstraint which requires SDF precomputation, this class queries
 * the BVH directly each frame. Best for dynamic meshes or when SDF resolution
 * would be prohibitively high.
 *
 * Supports two modes:
 * - `'triangles'` (default): For triangle meshes, uses signed distance for inside/outside detection
 * - `'points'`: For point clouds (like Gaussian Splat centers), uses pointRadius shell around each point
 *
 * @example
 * import { BVHVolumeConstraint } from '@three-blocks/core';
 * import { computeBoundsTree } from 'three-mesh-bvh';
 *
 * // Triangle mesh constraint (containment)
 * geometry.computeBoundsTree();
 * const containerConstraint = new BVHVolumeConstraint({
 *   geometry,
 *   mode: 'triangles',
 *   stiffness: 1000,
 *   containment: true // Keep particles inside
 * });
 *
 * // Point cloud constraint (collision with Gaussian Splats)
 * pointsGeometry.computeBoundsTree();
 * const splatsConstraint = new BVHVolumeConstraint({
 *   geometry: pointsGeometry,
 *   mode: 'points',
 *   pointRadius: 0.5, // Shell thickness around each point
 *   stiffness: 1000,
 * });
 *
 * // In simulation loop
 * await containerConstraint.apply(renderer, positionsBuffer, velocitiesBuffer, particleCount);
 * await splatsConstraint.apply(renderer, positionsBuffer, velocitiesBuffer, particleCount);
 *
 * @class BVHVolumeConstraint
 * @short Direct BVH boundary constraint without SDF precomputation.
 * @category Simulation
 * @tags WebGPU, Physics, BVH
 */
export class BVHVolumeConstraint {
    /**
     * Create a new BVH volume constraint.
     *
     * @param {Object} options - Configuration options
     * @param {THREE.BufferGeometry} options.geometry - Source geometry with BVH
     * @param {*} [options.bvh] - BVH from three-mesh-bvh (auto-retrieved from geometry.boundsTree if not provided)
     * @param {string} [options.mode='triangles'] - Mode: 'triangles' for meshes, 'points' for point clouds
     * @param {number} [options.stiffness=1000.0] - Boundary stiffness
     * @param {number} [options.damping=0.5] - Velocity damping
     * @param {number} [options.threshold=0.0] - Distance threshold for triangles mode (positive = offset from surface)
     * @param {number} [options.pointRadius=0.5] - Shell radius for points mode
     * @param {number} [options.maxSearchDistance=10.0] - Maximum BVH search distance
     * @param {boolean} [options.containment=false] - For triangles mode: if true, keep particles INSIDE; if false, push OUT
     * @param {THREE.Matrix4} [options.worldMatrix] - World transformation matrix for the mesh
     */
    constructor(options?: {
        geometry: THREE.BufferGeometry;
        bvh?: any;
        mode?: string;
        stiffness?: number;
        damping?: number;
        threshold?: number;
        pointRadius?: number;
        maxSearchDistance?: number;
        containment?: boolean;
        worldMatrix?: THREE.Matrix4;
    });
    /** @type {THREE.BufferGeometry} */
    geometry: THREE.BufferGeometry;
    /** @type {*} */
    bvh: any;
    /** @type {string} */
    mode: string;
    /** @type {number} */
    stiffness: number;
    /** @type {number} */
    damping: number;
    /** @type {number} */
    threshold: number;
    /** @type {number} */
    pointRadius: number;
    /** @type {number} */
    maxSearchDistance: number;
    /** @type {boolean} */
    containment: boolean;
    /** @type {THREE.Matrix4} */
    boundsMatrix: THREE.Matrix4;
    /** @type {THREE.Matrix4} */
    inverseBoundsMatrix: THREE.Matrix4;
    /** @private */
    private _computeNode;
    /** @private */
    private _cachedParticleCount;
    /** @private */
    private _cachedPositionsBuffer;
    /** @private */
    private _cachedVelocitiesBuffer;
    /** @private */
    private _indexBuffer;
    /** @private */
    private _positionBuffer;
    /** @private */
    private _nodeBuffer;
    /**
     * Builds GPU storage buffers from BVH data.
     * @private
     */
    private _buildBuffers;
    /**
     * Gets the index array from geometry.
     * @private
     * @param {THREE.BufferGeometry} geometry
     * @returns {Uint32Array}
     */
    private _getIndexArray;
    /**
     * Gets the position array from geometry.
     * @private
     * @param {THREE.BufferGeometry} geometry
     * @returns {Float32Array}
     */
    private _getPositionArray;
    /**
     * Sets the world transformation matrix for the BVH mesh.
     *
     * @param {THREE.Matrix4} matrix - World transformation matrix
     */
    setWorldMatrix(matrix: THREE.Matrix4): void;
    /**
     * Applies the BVH boundary constraint to particle buffers.
     *
     * @param {THREE.WebGPURenderer} renderer - WebGPU renderer
     * @param {THREE.StorageBufferAttribute} positionsBuffer - Particle positions
     * @param {THREE.StorageBufferAttribute} velocitiesBuffer - Particle velocities
     * @param {number} particleCount - Number of particles
     * @returns {Promise<void>}
     */
    apply(renderer: THREE.WebGPURenderer, positionsBuffer: THREE.StorageBufferAttribute, velocitiesBuffer: THREE.StorageBufferAttribute, particleCount: number): Promise<void>;
    /**
     * Updates the BVH data (for dynamic meshes).
     *
     * @param {THREE.BufferGeometry} geometry - Updated geometry
     * @param {*} [bvh] - Updated BVH (auto-retrieved from geometry.boundsTree if not provided)
     */
    updateBVH(geometry: THREE.BufferGeometry, bvh?: any): void;
    /**
     * Disposes GPU resources.
     */
    dispose(): void;
}
